/* War Room 13.9 · COURSES — every Acquisition.com course, built into the work instead of read about.
   Work → Courses. One module per course, each fed by your own data (dial log, pipeline, money, Playbook):
     Scaling Roadmap · $100M Offers · $100M Leads · $100M Money Models · $100M Sales Teams · Hormozi mindset · Wealth (in Money).
   The course's own rule decides what is open: "study only your stage, plus one before and one after". Stage comes from the
   same evidence stage.js uses (the call log), so later material is visible but marked with what opens it.
   State: S.acq, one record per item (checkbox, score, text), synced per item by _u. Paraphrased study notes, not quotes. */
'use strict';
let acqTab = 'home', acqQ = '';
const ACQ_TABS = [['home', 'All'], ['scale', 'Scaling'], ['offer', 'Offers'], ['leads', 'Leads'], ['mm', 'Money models'], ['sales', 'Sales'], ['mind', 'Mindset'], ['wealth', 'Wealth']];

/* ── store ── */
function acqV(k, d) { const r = (S.acq || {})[k]; return r && !r._del && r.v !== undefined ? r.v : d; }
function acqW(k, v, quiet) { S.acq = S.acq || {}; S.acq[k] = { id: k, v, _u: now() }; save(); if (!quiet) render(); }
function acqT(k) { acqW(k, !acqV(k, false)); }
function acqEv() { try { return sgEvidence(); } catch (e) { return { attempts: counterTotal('dials') || 0, answered: 0, conv: 0, dm: 0, demand: 0, requests: 0, working: 0, paid: 0, paidSum: 0, bench: 0, cb: 0 }; } }
const acqPct = (a, b) => (b ? Math.round((a / b) * 100) : 0);
function acqChecks(prefix, items) { const done = items.filter(([id]) => acqV(prefix + id, false)).length; return { done, n: items.length, html: `<div class="aq-checks">${items.map(([id, t, d]) => { const on = acqV(prefix + id, false); return `<button class="${on ? 'on' : ''}" onclick="acqT('${prefix + id}')"><i>${on ? '✓' : ''}</i><span><b>${t}</b>${d ? `<em>${d}</em>` : ''}</span></button>`; }).join('')}</div>` }; }
function acqField(k, ph, big) { return big ? `<textarea class="aq-in" placeholder="${esc(ph)}" onchange="acqW('${k}',this.value,true)">${esc(acqV(k, ''))}</textarea>` : `<input class="aq-in" placeholder="${esc(ph)}" value="${esc(acqV(k, ''))}" onchange="acqW('${k}',this.value,true)">`; }
function acqNum(k, d) { return Number(acqV(k, d)) || 0; }
function acqHead(t, sub, src) { return `<div class="aq-hd"><div><b>${t}</b><span>${sub}</span></div>${src ? `<em>${src}</em>` : ''}</div>`; }
function acqLock(why) { return `<div class="aq-lock"><b>Opens later</b><span>${why}</span></div>`; }

