function acqStage(e) { e = e || acqEv(); const auto = e.paid >= 1 ? 2 : (e.working >= 1 || e.demand >= 1) ? 1 : 0, man = acqV('sc:stage', null); return man == null ? auto : Number(man); }
function acqScale() {
  const e = acqEv(), cur = acqStage(e), auto = acqV('sc:stage', null) == null;
  const card = (i) => { const s = AQ_STAGES[i]; if (!s) return ''; const rel = i === cur ? 'now' : i < cur ? 'before' : 'next';
    if (!s.items) return `<div class="card aq-stg ${rel}"><div class="aq-stg-h"><b>${i} · ${s.n}</b><span>${s.h} · founder = ${s.role}</span></div><div class="aq-line">${s.line}</div></div>`;
    const c = acqChecks('sc:' + i + ':', s.items.map((it, j) => [j, it[0], it[1]])), first = s.items.findIndex((it, j) => !acqV('sc:' + i + ':' + j, false));
    return `<div class="card aq-stg ${rel}"><div class="aq-stg-h"><b>${i} · ${s.n}${rel === 'now' ? ' · YOU ARE HERE' : rel === 'next' ? ' · next' : ' · before'}</b><span>${s.h} · founder = ${s.role} · ${c.done}/${c.n}</span></div>
      <div class="aq-line">${s.line}</div>${rel === 'now' && first >= 0 ? `<div class="aq-con"><span>The constraint now · ${AQ_FN[first]}</span><b>${s.items[first][0]}</b></div>` : ''}
      <div class="aq-fn">${s.items.map((it, j) => `<i>${AQ_FN[j]}</i>`).join('')}</div>${c.html}</div>`; };
  return `${acqHead('Scaling Roadmap', 'The 10 stages are set by headcount, not revenue. Study only your stage, one before and one after.', 'Scaling 1–12')}
    <div class="aq-ladder">${AQ_STAGES.map((s, i) => `<button class="${i === cur ? 'cur' : ''} ${Math.abs(i - cur) <= 1 ? 'open' : 'far'}" onclick="acqW('sc:stage',${i})"><b>${i}</b><span>${s.n}</span></button>`).join('')}</div>
    <div class="aq-note">${auto ? `Set from your log: ${e.paid ? 'a payment has arrived' : e.working || e.demand ? 'an agency is trying it' : 'nobody has tried it yet'}. Tap a stage to override.` : `You set this by hand. <a href="#" onclick="acqW('sc:stage',null);return false">Back to automatic</a>`}</div>
    ${card(cur)}${card(cur + 1)}${cur > 0 ? `<details class="aq-more"><summary>Stage before: ${AQ_STAGES[cur - 1].n}</summary>${card(cur - 1)}</details>` : ''}
    <details class="aq-more"><summary>All 10 stages</summary><div class="card">${AQ_STAGES.map((s, i) => `<div class="aq-kv"><span>${i} · ${s.n} <em>${s.h}</em></span><b>${s.line}</b></div>`).join('')}</div></details>`;
}

/* ═════════ $100M OFFERS ═════════ */
const AQ_VE = [['d', 'Dream outcome', 'How big the result is to them', 'Bigger, more specific result; solve a bigger problem; niche the avatar.'], ['l', 'Perceived likelihood', 'How sure they are it works for them', 'Proof that looks like them, a named guarantee, the 10,000th surgery effect.'], ['t', 'Time delay', 'How long until the first and the final result', 'Fast beats free: first profiles within 3 days, show progress daily.'], ['e', 'Effort & sacrifice', 'What they must do, stop doing or endure', 'Done-for-you: you post, screen, confirm; they only interview.']];
const AQ_PROB = [['nos', 'Interviewees and new hires don\'t show up', 'l', 'Every caregiver confirmed twice; no-show → replacement profile within 24 h (Show-Up Guarantee)'], ['slow', 'It takes weeks to get anyone decent', 't', '2–3 screened local profiles within 3 days'], ['quit', 'New hires quit in the first 90 days', 'l', 'Check-ins on days 1, 3, 7, 14, 30, 90; free replacement (90-Day Stay-or-Replace)'], ['time', 'Screening eats the owner\'s week', 'e', 'Phone-screened by a person before they ever see a profile'], ['risk', 'Paying for nothing, recruiters burned them', 'l', 'The first caregiver who works the case is free'], ['hard', 'Hard cases: 24/7, live-in, weekends, far towns', 'd', 'Ads for that exact case the same day; hard-case pricing']];
function acqOffer() {
  const sc = (who) => { const v = {}; AQ_VE.forEach(([k]) => (v[k] = acqNum('of:ve:' + who + ':' + k, 5))); return v; }, me = sc('me'), them = sc('them');
  const val = (v) => (v.d * v.l) / Math.max(1, v.t * v.e), worst = AQ_VE.map(([k, n, , fix]) => ({ k, n, fix, s: k === 't' || k === 'e' ? 11 - me[k] : me[k] })).sort((a, b) => a.s - b.s)[0];
  const slider = (who, k) => `<i class="aq-who">${who === 'me' ? 'You' : 'Them'}</i><input type="range" min="1" max="10" value="${(who === 'me' ? me : them)[k]}" oninput="this.nextElementSibling.textContent=this.value" onchange="acqW('of:ve:${who}:${k}',Number(this.value))"><b>${(who === 'me' ? me : them)[k]}</b>`;
  const mk = ['m', 'a', 'g', 'i', 'c'], MAG = { m: 'Magnetic reason why', a: 'Announce the avatar', g: 'Give a goal', i: 'Indicate a time', c: 'Complete with a container word' }, magN = mk.filter((x) => acqV('of:mag:' + x, false)).length;
  const price = acqNum('of:price', 2500), cost = acqNum('of:cost', 0), gm = price ? (price - cost) / price : 0;
  const mkt = [['pain', 'Massive pain', 'Open cases cost them billable hours every week'], ['buy', 'Purchasing power', 'Private-pay agencies bill $30+/hour'], ['target', 'Easy to target', 'Licensed agency lists by county'], ['grow', 'Growing', 'Ageing population; caregiver shortage']];
  return `${acqHead('$100M Offers', 'Make an offer so good people feel stupid saying no. Market first, then offer, then persuasion.', 'Offers 1–10')}
    <div class="card"><div class="aq-t">1 · Starving crowd <span>score your market 1–5 on each</span></div>${mkt.map(([k, n, h]) => `<div class="aq-score"><span><b>${n}</b><em>${h}</em></span><div class="aq-5">${[1, 2, 3, 4, 5].map((x) => `<button class="${acqNum('of:mk:' + k, 0) >= x ? 'on' : ''}" onclick="acqW('of:mk:${k}',${x})">${x}</button>`).join('')}</div></div>`).join('')}
      <div class="aq-note">If one of the four is missing, the course says pick another market. Riches are in niches: same product, tighter avatar, higher price.</div></div>
    <div class="card"><div class="aq-t">2 · Value Equation <span>(dream × likelihood) ÷ (time × effort)</span></div>
      <div class="aq-ve"><div></div><b>Your offer</b><b>Their usual way</b>${AQ_VE.map(([k, n, h]) => `<div><b>${n}</b><em>${h}${k === 't' || k === 'e' ? ' · lower is better' : ''}</em></div><div class="aq-sl">${slider('me', k)}</div><div class="aq-sl">${slider('them', k)}</div>`).join('')}
        <div><b>Value</b></div><div class="aq-vv">${val(me).toFixed(1)}</div><div class="aq-vv">${val(them).toFixed(1)}</div></div>
      <div class="aq-con"><span>Weakest lever</span><b>${worst.n}</b><em>${worst.fix}</em></div></div>
    <div class="card"><div class="aq-t">3 · Dream outcome sentence <span>[avatar] get [outcome] in [time] without [what they fear]</span></div>
      <div class="aq-g2">${acqField('of:do:a', 'Avatar · e.g. Tampa private-pay agency owners')}${acqField('of:do:o', 'Outcome · e.g. every open case staffed')}${acqField('of:do:t', 'Time · e.g. within 3 days')}${acqField('of:do:w', 'Without · e.g. no-shows or paying for nothing')}</div>
      <div class="aq-say">${esc([acqV('of:do:a', ''), acqV('of:do:o', '') ? 'get ' + acqV('of:do:o', '') : '', acqV('of:do:t', ''), acqV('of:do:w', '') ? 'without ' + acqV('of:do:w', '') : ''].filter(Boolean).join(' ') || 'Fill the four boxes.')}</div></div>
    <div class="card"><div class="aq-t">4 · Problems → solutions → trim & stack <span>from your Call 1 pitch; rate value and cost 1–5</span></div>
      ${AQ_PROB.map(([k, p, lv, sol]) => { const v = acqNum('of:pv:' + k, 4), c = acqNum('of:pc:' + k, 2), tag = v <= 2 ? 'cut' : c >= 4 ? 'heavy' : 'keep'; return `<div class="aq-prob"><div><b>${esc(p)}</b><em>${AQ_VE.find((x) => x[0] === lv)[1]} · ${esc(sol)}</em></div><div class="aq-vc"><label>value<select onchange="acqW('of:pv:${k}',Number(this.value))">${[1, 2, 3, 4, 5].map((x) => `<option ${x === v ? 'selected' : ''}>${x}</option>`).join('')}</select></label><label>cost<select onchange="acqW('of:pc:${k}',Number(this.value))">${[1, 2, 3, 4, 5].map((x) => `<option ${x === c ? 'selected' : ''}>${x}</option>`).join('')}</select></label><i class="t-${tag}">${tag === 'cut' ? 'CUT' : tag === 'heavy' ? 'HEAVY HITTER' : 'KEEP'}</i></div></div>`; }).join('')}
      <div class="aq-note">Keep high value. Allow only 1–2 high-cost items (the heavy hitters). Cut anything low value even if it is cheap. ${AQ_PROB.filter(([k]) => acqNum('of:pc:' + k, 2) >= 4).length > 2 ? '<b class="bad">More than 2 heavy hitters: trim.</b>' : ''}</div></div>
    <div class="card"><div class="aq-t">5 · Enhance: scarcity, urgency, bonuses, guarantee, name</div>
      ${acqChecks('of:en:', [['sc', 'Scarcity is real and said out loud', 'Max 2 members per town area.'], ['ur', 'Urgency has a reason', 'Rolling cohort, season, time-limited bonus, or a real closing window.'], ['bo', 'Bonuses instead of discounts, each named with its benefit', 'Total bonus value bigger than the core. Tools and checklists beat hours.'], ['gu', 'Guarantee in the form "if not X in Y, we Z"', 'Show-Up Guarantee + 90-Day Stay-or-Replace, named on every pitch.'], ['fp', 'Free or full price, never a discount', 'Change the plan, never the number.']]).html}
      <div class="aq-t" style="margin-top:12px">MAGIC name check <span>${magN}/5 · aim for 3–5</span></div>${acqField('of:name', 'The name you say on the phone · e.g. First Hire Free')}
      <div class="aq-chips">${mk.map((x) => `<button class="${acqV('of:mag:' + x, false) ? 'on' : ''}" onclick="acqT('of:mag:${x}')"><b>${x.toUpperCase()}</b> ${MAG[x]}</button>`).join('')}</div></div>
    <div class="card"><div class="aq-t">6 · Charge what it's worth <span>services need ≥ 80% gross margin</span></div>
      <div class="aq-g2"><label class="aq-lb">Price every 4 weeks ($)<input class="aq-in" type="number" value="${price}" onchange="acqW('of:price',Number(this.value))"></label><label class="aq-lb">Cost to deliver per client ($: ads + your screening hours)<input class="aq-in" type="number" value="${cost || ''}" placeholder="0" onchange="acqW('of:cost',Number(this.value))"></label></div>
      <div class="aq-big ${gm >= 0.8 ? 'ok' : 'bad'}">${Math.round(gm * 100)}% gross margin</div><div class="aq-note">${gm >= 0.8 ? 'Room for acquisition, admin and profit.' : 'Below 80%: raise the price or cut delivery cost before scaling.'} Price is a filter: higher price, more committed clients, better results.</div></div>`;
}

